"""Lazy, composable transformations of iterable targets."""
import itertools

from boltons.iterutils import chunked_iter, windowed_iter

from .core import (T, Path, TargetRegistry, glom, SKIP, STOP, _MISSING)


class First(object):
    """Return the first item whose *key* subspec is truthy, or *default*."""
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        for item in iterate(target):
            result = scope[glom](item, self.key, scope)
            if result is STOP:
                break
            if result is not SKIP and result:
                return item
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


class Iter(object):
    """Build a lazy iterable pipeline.

    Each item is evaluated against *subspec*. SKIP drops an item and STOP
    terminates iteration. Transformations return new specifiers, leaving the
    original pipeline reusable. Use ``all()`` to collect results in a list.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._ops = ()

    def _with(self, name, *args):
        ret = type(self)(self.subspec, sentinel=self.sentinel)
        ret._ops = self._ops + ((name, args),)
        return ret

    def map(self, subspec=T):
        return self._with('map', subspec)

    def filter(self, key=T):
        return self._with('filter', key)

    def chunked(self, size, fill=_MISSING):
        if not isinstance(size, int) or size <= 0:
            raise ValueError('size must be a positive integer')
        return self._with('chunked', size, fill)

    def windowed(self, size):
        if not isinstance(size, int) or size <= 0:
            raise ValueError('size must be a positive integer')
        return self._with('windowed', size)

    def flatten(self):
        return self._with('flatten')

    def unique(self, key=T):
        return self._with('unique', key)

    def dropwhile(self, key=T):
        return self._with('dropwhile', key)

    def takewhile(self, key=T):
        return self._with('takewhile', key)

    def slice(self, *args):
        # Validate immediately, rather than on the first iteration.
        itertools.islice((), *args)
        return self._with('slice', *args)

    def limit(self, count):
        return self.slice(count)

    def all(self):
        return (self, list)

    def first(self, key=T, default=None):
        return (self, First(key, default))

    def _map(self, iterator, subspec, scope):
        for i, item in enumerate(iterator):
            child = scope.new_child({Path: scope[Path] + [i]})
            value = scope[glom](item, subspec, child)
            if value is STOP or value is self.sentinel:
                break
            if value is not SKIP:
                yield value

    @staticmethod
    def _filter(iterator, key, scope):
        for item in iterator:
            value = scope[glom](item, key, scope)
            if value is STOP:
                break
            if value is not SKIP and value:
                yield item

    @staticmethod
    def _unique(iterator, key, scope):
        seen = set()
        for item in iterator:
            value = scope[glom](item, key, scope)
            if value not in seen:
                seen.add(value)
                yield item

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target, path=scope[Path])
        iterator = self._map(iterate(target), self.subspec, scope)
        for name, args in self._ops:
            if name == 'map':
                iterator = self._map(iterator, args[0], scope)
            elif name == 'filter':
                iterator = self._filter(iterator, args[0], scope)
            elif name == 'chunked':
                kw = {} if args[1] is _MISSING else {'fill': args[1]}
                iterator = chunked_iter(iterator, args[0], **kw)
            elif name == 'windowed':
                iterator = windowed_iter(iterator, args[0])
            elif name == 'flatten':
                iterator = itertools.chain.from_iterable(iterator)
            elif name == 'unique':
                iterator = self._unique(iterator, args[0], scope)
            elif name in ('dropwhile', 'takewhile'):
                def predicate(item, key=args[0]):
                    value = scope[glom](item, key, scope)
                    return value is not SKIP and value is not STOP and bool(value)
                iterator = getattr(itertools, name)(predicate, iterator)
            elif name == 'slice':
                iterator = itertools.islice(iterator, *args)
        return iterator

    def __repr__(self):
        text = 'Iter(%r)' % (self.subspec,)
        for name, args in self._ops:
            text += '.%s(%s)' % (name, ', '.join(repr(a) for a in args))
        return text
